	,IfcAxis2Placement3D
	,IfcAxis2PlacementLinear))
 SUBTYPE OF (IfcGeometricRepresentationItem);
	Location : IfcPoint;
 DERIVE
	Dim : IfcDimensionCount := Location.Dim;
END_ENTITY;

entity_definitions.IfcPoint:
