	(IfcCartesianPoint
	,IfcPointByDistanceExpression
	,IfcPointOnCurve
	,IfcPointOnSurface))
 SUBTYPE OF (IfcGeometricRepresentationItem);
 DERIVE
	Dim : IfcDimensionCount := IfcPointDim(SELF);
END_ENTITY;

entity_definitions.IfcSegment:
