entity_definitions.IfcRectangularTrimmedSurface:
ENTITY IfcRectangularTrimmedSurface
 SUBTYPE OF (IfcBoundedSurface);
	BasisSurface : IfcSurface;
	U1 : IfcParameterValue;
	V1 : IfcParameterValue;
	U2 : IfcParameterValue;
	V2 : IfcParameterValue;
	Usense : IfcBoolean;
	Vsense : IfcBoolean;
 WHERE
	U1AndU2Different : U1 <> U2;
	UsenseCompatible : (('IFC4X3_ADD2_DEV_20260526.IFCELEMENTARYSURFACE' IN TYPEOF(BasisSurface)) AND
         (NOT ('IFC4X3_ADD2_DEV_20260526.IFCPLANE' IN TYPEOF(BasisSurface)))) OR
         ('IFC4X3_ADD2_DEV_20260526.IFCSURFACEOFREVOLUTION' IN TYPEOF(BasisSurface)) OR
         (Usense = (U2 > U1));
	V1AndV2Different : V1 <> V2;
	VsenseCompatible : Vsense = (V2 > V1);
END_ENTITY;

