	RelatingMaterial : IfcMaterialSelect;
 WHERE
	AllowedElements : SIZEOF(QUERY(temp <* SELF\IfcRelAssociates.RelatedObjects | (
  SIZEOF(TYPEOF(temp) * [   
    'IFC4X3_ADD2_DEV_20260526.IFCELEMENT', 
    'IFC4X3_ADD2_DEV_20260526.IFCELEMENTTYPE',
    'IFC4X3_ADD2_DEV_20260526.IFCSTRUCTURALMEMBER',
    'IFC4X3_ADD2_DEV_20260526.IFCPORT']) = 0) 
)) = 0;
	NoVoidElement : SIZEOF(QUERY(temp <* SELF\IfcRelAssociates.RelatedObjects | 
  ('IFC4X3_ADD2_DEV_20260526.IFCFEATUREELEMENTSUBTRACTION' IN TYPEOF(temp)) OR 
  ('IFC4X3_ADD2_DEV_20260526.IFCVIRTUALELEMENT' IN TYPEOF(temp)) 
