IfcAdvancedBrepWithVoids:
SIZEOF (QUERY (Vsh <* Voids |
  SIZEOF (QUERY (Afs <* Vsh.CfsFaces |
  (NOT ('IFC4X3_ADD2_DEV_20260526.IFCADVANCEDFACE' IN TYPEOF(Afs)))
  )) = 0
)) = 0
